use lapis_app_protocol::{ExpectedVersion, TextSnapshot, editing_intents::*};
use ts_rs::{Config, TS};

pub(super) fn declarations(config: &Config) -> Vec<String> {
    vec![
        EditingIntentState::decl(config),
        EditingIntentCommand::decl(config),
        EditingIntentValue::decl(config),
    ]
}

pub(super) fn typescript(config: &Config) -> String {
    let shared = [ExpectedVersion::decl(config), TextSnapshot::decl(config)];
    format!(
        "// Generated by pnpm protocol:generate. Do not edit.\n{}\n",
        shared
            .iter()
            .chain(declarations(config).iter())
            .map(|item| format!("export {item}"))
            .collect::<Vec<_>>()
            .join("\n")
    )
}
